	function upgradeTranslation () {
		init(true);				
		//1.0 has no upgrades
		if (gCurVersion  == CODEVERSION) {
			message("TRANSLATE: latest version ("+gCurVersion+") is installed")
		} else {
			upgraded = false
			if (gCurVersion == "0.9") {
				upgrade09_to_10();
				gCurVersion = "1.0";
				upgraded = true
			}
			if (gCurVersion == "1.0") {
				upgrade10_to_11();
				gCurVersion = "1.1";
				upgraded = true
			}
			if (gCurVersion == "1.1") {
				upgrade11_to_12();
				gCurVersion = "1.2";
				upgraded = true
			}
			if (gCurVersion == "1.2") {
				upgrade12_to_13();
				gCurVersion = "1.3";
				upgraded = true
			}
			if (gCurVersion == "1.3") {
				upgrade13_to_14();
				gCurVersion = "1.4";
				upgraded = true
			}
			if (upgraded) {
				updTranslInfo(gCurrentLang, gLanguages
					 ,CODEVERSION,curDateStr());	
				message("TRANSLATE: latest version ("+CODEVERSION+") is now installed")
			} else {
			error("\nTRANSLATE: unknown version ("+gCurVersion+").\n"
					+"Please contact support\n");
			}
		}			
	}

