	if (returnVal == Filebrowse.APPROVE_OPTION) {
		imppath = f.getSelectedFile();
		//message(imppath);
	} else {
		return
	}
	tabanz = 0
	colanz = 0
	colmapanz = 0
	lineanz = 0
	logicalModel = model.getDesign().getLogicalDesign();
	entitySet = logicalModel.getEntitySet()
	relationSet = logicalModel.getRelationSet()
	inheritanceSet = logicalModel.getInheritanceRelationSet()
	importFile(imppath);
	message("Parsed " + lineanz + " lines from file " + imppath + ".\n" +
			"Created " + tabanz + " tables, " + colanz + " columns,\n" +
			"Mapped " + tabmapanz + " tables to entities and " + colmapanz + " columns to attributes") // +tabmapanz+" table- and " 

}

