lib.script:
			//scripts to handle translation of model
	var CODEVERSION = '1.4';
	var gLogNote = "LOG";
	var gParams={}
	var gTranslInforegexp =/TRANSLATION\{([^}]*)\}/;
	var logInitialized = false;
	var NOTESSTARTTAG = '[<tag>[';
	var NOTESENDTAG = ']<tag>]';
	var PLAINMESSAGE = 1;
	var ERRORMESSAGE = 0;
	var WARNINGMESSAGE = 2;
	var QUESTIONMESSAGE = 3;
	var translation = false

//	var DEEPLAuthKey = "9043d070-26fd-f874-6b80-37ddc4b6367c"
	var DEEPLURL = "https://api.deepl.com/v2/translate"
	var DEEPLURL2 = "https://api.deepl.com/v2/usage"

	function fullmessage(msg,type) {
		Java.type("javax.swing.JOptionPane").showMessageDialog(null
		, msg,'ODM-Translation', type);
	}

	function error(msg) {
		fullmessage(msg,ERRORMESSAGE);
		}
	function message(msg) {
		fullmessage(msg,PLAINMESSAGE);
		}

		function getCurrentLang() {return gParams["currentLang"];}
		function setCurrentLang(lang) {gParams["currentLang"] = lang;}
		function getVersion() {return gParams["version"];}
		function setVersion(version) {gParams["version"] = version;}
		function getLastSync() {return gParams["lastSync"];}
		function setLastSync(lastSync) {return gParams["lastSync"] = lastSync;}
		function getLanguages() {return gParams["languages"];}
		function getLangArr() {return getLanguages().split(',');}
		function getDEEPLAuthKey() {
			 if ('DEEPLAuthKey' in gParams) {return gParams['DEEPLAuthKey']}
			 else {return null}
		}

function linemessage() {
	str = ''
	for (i=0;i<arguments.length;i++){
		str = str.concat(arguments[i],'\n')
	}
	Java.type("javax.swing.JOptionPane").showMessageDialog(null, str, 'Testjs', 1);
}

function translconn(purl){
	URL =  Java.type("java.net.URL")
	url = new URL(purl)
	con = url.openConnection();
	con.setRequestMethod("GET");
	con.setRequestProperty("Content-Type", "application/json; utf-8");
	con.setRequestProperty("Accept", "application/json");
	con.setRequestProperty("Accept-Charset", "utf-8");
	con.setDoOutput(true);
	return con
	//try {os = con.getOutputStream()}
	//	catch (err){message("os= "+err.toString())}
	//var mybuffer = [];
	//try {os.write(mybuffer,0,mybuffer.length)
	//	}
	//	catch (err){message('write='+err.toString())}
}

function Utf8ArrayToStr(array) {
  var out, i, len, c;
  var char2, char3;

  out = "";
  len = array.length;
  i = 0;
  while (i < len) {
    c = array[i++];
    switch (c >> 4)
    { 
      case 0: case 1: case 2: case 3: case 4: case 5: case 6: case 7:
        // 0xxxxxxx
        out += String.fromCharCode(c);
        break;
      case 12: case 13:
        // 110x xxxx   10xx xxxx
        char2 = array[i++];
        out += String.fromCharCode(((c & 0x1F) << 6) | (char2 & 0x3F));
        break;
      case 14:
        // 1110 xxxx  10xx xxxx  10xx xxxx
        char2 = array[i++];
        char3 = array[i++];
        out += String.fromCharCode(((c & 0x0F) << 12) |
                                   ((char2 & 0x3F) << 6) |
                                   ((char3 & 0x3F) << 0));
        break;
    }
  }    
  return out;
}
function getanswer(inputstr){
	var buf = []
	var b = inputstr.read()
	while (b != -1) {
		buf.push(b)
		b = inputstr.read()
	}
	return Utf8ArrayToStr(buf)
}

function haveDeeplAccess(){
	var urlu = DEEPLURL2+"?auth_key="+getDEEPLAuthKey()
	var conu = translconn(urlu)

	try {
		s = getanswer(conu.getInputStream())
		json = JSON.parse(s)
		//message2(urlu,JSON.stringify(json))
		return true
	}
	catch (err){return false}
}

function translate(fromlang,tolang,text){
	var url = DEEPLURL
		+"?auth_key="+getDEEPLAuthKey()
		+"&text="+encodeURI(text)
		+"&target_lang="+tolang
		+"&source_lang="+fromlang
	var con = translconn(url)

	try {
		s = getanswer(con.getInputStream())
		json = JSON.parse(s)
		//message2(url,JSON.stringify(json))
		return json["translations"][0]["text"]
	}
	catch (err){message(err.toString())}
}

