	function upgradeTranslation () {
		init(true);				
		//1.0 has no upgrades
		if (getVersion()  == CODEVERSION) {
			message("TRANSLATE: latest version ("+getVersion()+") is installed")
		} else {
			upgraded = false
			if (getVersion() == "0.9") {
				upgrade09_to_10();
				setVersion("1.0");
				upgraded = true
			}
			if (getVersion() == "1.0") {
				upgrade10_to_11();
				setVersion("1.1");
				upgraded = true
			}
			if (getVersion() == "1.1") {
				upgrade11_to_12();
				setVersion("1.2");
				upgraded = true
			}
			if (getVersion() == "1.2") {
				upgrade12_to_13();
				setVersion("1.3");
				upgraded = true
			}
			if (getVersion() == "1.3") {
				upgrade13_to_14();
				setVersion("1.4");
				upgraded = true
			}
			if (upgraded) {
				setVersion(CODEVERSION)
				setTranslInfo();	
				message("TRANSLATE: latest version ("+CODEVERSION+") is now installed")
			} else {
			error("\nTRANSLATE: unknown version ("+getVersion()+").\n"
					+"Please contact support\n");
			}
		}			
	}

